import {html as esc} from './workshop-model.js';
import {normalizeSearch} from './companion.js';
export function filterSpells(spells,{query='',category='all',form='all'}={}) {
 const q=normalizeSearch(query);
 return spells.filter(s=>(category==='all'||s.category===category)&&(form==='all'||s.cloth===form)&&normalizeSearch([s.name,s.title,s.summary,s.category,...s.catalysts.map(c=>c.id)].join(' ')).includes(q));
}
export function morganBudget({current,target,cap,kind='adult'},config){
 const start=Number(current),goal=Number(target),limit=Number(cap);
 const ceiling=Math.min(limit,config.POWER_CONSOLIDATION_ATTACK_CAP),gain=kind==='child'?config.MORGAN_CHILD_INCREASE:config.MORGAN_ADULT_INCREASE;
 if(![start,goal,limit,gain].every(Number.isFinite)||start<0||limit<0||start>ceiling||goal<start||goal>ceiling||gain<=0)return {error:'Usa daño almacenado válido: actual ≤ objetivo ≤ mínimo(límite innato, techo del pack).'};
 const kills=Math.max(0,Math.ceil(Math.max(0,goal-start)/gain-1e-9));
 return {kills,mana:kills*config.MORGAN_UPGRADE_MANA_COST,gain,ceiling};
}
export function catalystBudget(spell,count,method='mortar',scroll=true){
 const quantity=Number(count);if(!Number.isInteger(quantity)||quantity<1||quantity>10000)return {error:'Elige entre 1 y 10,000 círculos.'};
 if(scroll&&spell.cloth==='forbidden')return {error:'Este hechizo solo admite círculo en el suelo.'};
 const useCloth=spell.cloth==='required'||scroll,yieldCount=method==='hammer'?1:2;
 return {quantity,cloth:useCloth?quantity:0,tools:method==='hammer'?'Hammer':'Mortar and Pestle',powders:spell.catalysts.map(c=>({id:c.id,count:c.count*quantity,raw:Math.ceil(c.count*quantity/yieldCount),surplus:Math.ceil(c.count*quantity/yieldCount)*yieldCount-c.count*quantity}))};
}
const formName={required:'Pergamino · tela obligatoria',optional:'Círculo o pergamino',forbidden:'Solo círculo en suelo'};
const format=n=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(n);
const links=sources=>sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('');
export function createMahou(c){
 const {data,icon,name,state,navigate}=c;
 let tab='overview',selected='',spellQuery='',spellCategory='all',spellForm='all',configQuery='',configOnlyChanges=true;
 const routes=new Set(['overview','guides','roadmap','spells','tools','settings']);
 function route(path=''){const parts=path.split('/');tab=routes.has(parts[0])?parts[0]:'overview';selected=parts.slice(1).join('/');}
 const btn=(path,label,primary=false)=>`<button class="btn ${primary?'btn-primary':''}" data-mahou="${esc(path)}">${esc(label)}</button>`;
 function progress(){const keys=data.roadmap.flatMap(r=>r.checks);return {total:keys.length,done:keys.filter(k=>state().tasks[k]).length};}
 function header(){const p=progress();return `<div class="mh-header"><div><span class="eyebrow">GRIMORIO DE CAMPO · ATM10 8.1</span><h1>Mahou Tsukai</h1><p>Del primer círculo a tu propia especialidad.</p></div><div class="mh-progress"><span>${p.done} / ${p.total} objetivos</span><progress value="${p.done}" max="${p.total}" aria-label="Progreso de Mahou Tsukai"></progress><small>${esc(data.version)} · progreso local</small></div></div><nav class="mh-tabs" aria-label="Secciones de Mahou Tsukai">${[['overview','Inicio'],['roadmap','Roadmap'],['guides','Guías detalladas'],['spells','Grimorio · '+data.spells.length],['tools','Calculadoras'],['settings','Ajustes ATM10']].map(([id,label])=>`<button data-mahou="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${esc(label)}</button>`).join('')}</nav>`;}
 function overview(){const p=progress(),next=data.roadmap.find(r=>r.checks.some(k=>!state().tasks[k]))||data.roadmap.at(-1);return `<section class="mh-hero blueprint-sheet"><div><span class="eyebrow">TU SIGUIENTE PASO</span><h2>${esc(next.title)}</h2><p>${esc(next.goal)}</p><div class="gap-row">${btn('guides/'+next.guide,'Abrir guía →',true)}${btn('roadmap','Ver mi roadmap')}</div><div class="mh-hero-stats"><span><b>${data.chapters.length}</b> guías</span><span><b>${data.spells.length}</b> hechizos</span><span><b>${data.recipeCount}</b> crafteos</span><span><b>${p.total}</b> objetivos</span></div></div><svg viewBox="0 0 260 260" class="mh-sigil" role="img" aria-label="Diagrama decorativo de un círculo mágico"><g fill="none" stroke="currentColor"><circle cx="130" cy="130" r="108"/><circle cx="130" cy="130" r="94" stroke-dasharray="2 9"/><circle cx="130" cy="130" r="78"/><path d="M130 30 216 180H44Z M130 230 44 80H216Z"/><circle cx="130" cy="130" r="34"/><path d="M118 130h24m-12-12v24"/>${[0,60,120,180,240,300].map(a=>`<circle cx="130" cy="22" r="5" transform="rotate(${a} 130 130)"/>`).join('')}</g></svg></section><div class="mh-callout"><strong>Edición fijada al pack.</strong> Cap de Caliburn/Morgan: <b>${data.values.POWER_CONSOLIDATION_ATTACK_CAP}</b> · maná personal máximo: <b>${format(data.values.MAX_MANA_CAP)}</b>. Los catalizadores están cotejados con el JAR ${esc(data.version)}. Las explicaciones usan el compendio y la wiki del autor; las diferencias se señalan.</div><div class="section-heading"><h2>Elige una ruta de lectura</h2></div><div class="mh-guide-grid">${data.chapters.map((g,i)=>`<button class="paper-panel mh-guide-card" data-mahou="guides/${g.id}"><span class="mh-card-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(g.title)}</h3><p>${esc(g.summary)}</p><span class="mh-card-link">${g.sections.length} apartados · Abrir →</span></button>`).join('')}</div><section class="mh-bottom paper-panel"><h2>Todo conectado a tu taller</h2><p>Consulta recetas, marca los objetivos y exporta el progreso desde Mi bitácora. El roadmap es una propuesta de aprendizaje: el mod no impone este árbol de desbloqueos.</p><div class="gap-row"><button class="btn" data-addon-recipes="mahoutsukai">Ver recetas en el atlas</button><button class="btn" data-view="notes">Mi bitácora y respaldo</button>${btn('settings','Fuentes y diferencias')}</div></section>`;}
 function guide(){const g=data.chapters.find(g=>g.id===selected);if(!g)return `<h2>Guías de principio a fin</h2><p>Elige un capítulo. Cada uno incluye preparación, pasos, comprobaciones y fuentes.</p><div class="mh-guide-grid">${data.chapters.map(g=>`<button class="paper-panel mh-guide-card" data-mahou="guides/${g.id}"><h3>${esc(g.title)}</h3><p>${esc(g.summary)}</p><span class="mh-card-link">Leer guía →</span></button>`).join('')}</div>`;const index=data.chapters.indexOf(g);return `<div class="mh-reading"><aside class="mh-index"><strong>En esta guía</strong>${g.sections.map((s,i)=>`<button data-mh-scroll="mh-section-${i}">${String(i+1).padStart(2,'0')} ${esc(s.title)}</button>`).join('')}<hr>${btn('roadmap','Mi progreso')}${btn('spells','Consultar un hechizo')}</aside><article class="mh-article"><span class="eyebrow">CAPÍTULO ${index+1} / ${data.chapters.length}</span><h2>${esc(g.title)}</h2><p class="mh-lead">${esc(g.summary)}</p><div class="mh-item-strip">${g.items.map(id=>`<button data-item="${esc(id)}" class="btn">${icon(id)}${esc(name(id))}</button>`).join('')}</div>${g.sections.map((s,i)=>`<section id="mh-section-${i}" class="mh-reading-section"><h3><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h3><ol>${s.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section>`).join('')}<section class="mh-checks paper-panel"><h3>Comprueba tu avance</h3>${g.checklist.map((t,i)=>check(`pack:mahou-${g.id}-${i}`,t)).join('')}</section>${g.spells.length?`<h3>Hechizos de este capítulo</h3><div class="gap-row">${g.spells.map(id=>data.spells.find(s=>s.id===id)).filter(Boolean).map(s=>btn('spells/'+s.id,s.title)).join('')}</div>`:''}<div class="mh-sources"><strong>Fuentes del capítulo</strong>${links(g.sources)}<small>Las cifras del pack se cotejan en Ajustes ATM10. La wiki actual documenta una versión posterior; no es una prueba ejecutada en Minecraft.</small></div><div class="mh-prev-next">${index?btn('guides/'+data.chapters[index-1].id,'← Capítulo anterior'):''}${index<data.chapters.length-1?btn('guides/'+data.chapters[index+1].id,'Siguiente capítulo →',true):btn('roadmap','Volver al roadmap',true)}</div></article></div>`;}
 function check(key,title){return `<label class="mh-check ${state().tasks[key]?'completed':''}"><input type="checkbox" data-task="${esc(key)}" ${state().tasks[key]?'checked':''}><span>${esc(title)}</span></label>`;}
 function roadmap(){const p=progress();return `<div class="section-heading"><div><h2>Roadmap de aprendizaje</h2><p>Marca lo que ya comprobaste en tu mundo. Las ramas avanzadas son opcionales.</p></div><span class="badge gold">${p.done} / ${p.total}</span></div><p class="mh-muted">Orden editorial, sin bloqueos artificiales. Los logros del mod no desbloquean automáticamente estos hechizos. El progreso se comparte con las guías y Rutas y objetivos.</p><div class="mh-roadmap">${data.roadmap.map((r,i)=>{const done=r.checks.filter(k=>state().tasks[k]).length;return `<section class="mh-roadmap-stage ${done===r.checks.length?'complete':''}"><div class="mh-roadmap-rail"><span>${String(i+1).padStart(2,'0')}</span></div><div class="paper-panel"><div class="compact-section"><span class="eyebrow">${esc(r.branch)}</span><span class="badge ${done===r.checks.length?'gold':'muted'}">${done} / ${r.checks.length}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.goal)}</p><p class="mh-muted">Antes: ${esc(r.before)}</p>${r.checks.map((k,j)=>check(k,data.chapters.find(g=>g.id===r.guide).checklist[j])).join('')}${btn('guides/'+r.guide,'Abrir instrucciones →')}</div></section>`;}).join('')}</div>`;}
 function spellList(){const list=filterSpells(data.spells,{query:spellQuery,category:spellCategory,form:spellForm});return `<p class="mh-result-count" role="status">${list.length} de ${data.spells.length} hechizos</p><div class="mh-spell-grid">${list.map(s=>`<button class="paper-panel mh-spell-card" data-mahou="spells/${esc(s.id)}"><div class="compact-section"><span class="eyebrow">${esc(s.category)}</span><span>↗</span></div><h3>${esc(s.title)}</h3><small>${esc(s.name)}</small><p>${esc(s.summary)}</p><div class="mh-powders">${s.catalysts.map(i=>`<span>${icon(i.id)}${i.count}× ${esc(name(i.id))}</span>`).join('')}</div><span class="mh-form">${esc(formName[s.cloth])}</span></button>`).join('')}</div>${list.length?'':'<div class="empty-state"><h3>No hay coincidencias</h3><p>Prueba un nombre en español o inglés y revisa los filtros.</p><button class="btn" data-mh-reset>Limpiar filtros</button></div>'}`;}
 function spells(){const s=data.spells.find(s=>s.id===selected);if(s)return `<article class="mh-spell-detail mh-article">${btn('spells','← Todos los hechizos')}<span class="eyebrow mh-block">${esc(s.category)}</span><h2>${esc(s.title)}</h2><p class="mh-lead">${esc(s.name)} · ${esc(s.summary)}</p><div class="mh-callout"><strong>${esc(formName[s.cloth])}</strong><div class="mh-powders">${s.catalysts.map(i=>`<span>${icon(i.id)}${i.count}× ${esc(name(i.id))}</span>`).join('')}</div><small>Combinación de tres catalizadores verificada en ${esc(data.version)}. La tabla de crafteo y los rituales son procesos diferentes.</small></div><h3>Cómo prepararlo y usarlo</h3><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Qué revisar si falla</h3><ul>${s.pitfalls.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="mh-muted">${esc(s.versionScope||'Mecánica resumida de la wiki oficial actual; consulta el compendio del pack si difiere.')}</p><div class="gap-row">${btn('tools/'+s.id,'Calcular catalizadores',true)}${btn('settings','Consultar costes y límites')}</div>${check('mahou:spell:'+s.id,'Ya lo probé en mi mundo')}<div class="mh-sources">${links([{label:'Página oficial del hechizo',url:s.sourceUrl},{label:'Catalizadores extraídos del JAR',url:'data/mahou-rituals.json'}])}</div></article>`;return `<h2>Grimorio de hechizos</h2><p>Busca por efecto, nombre o catalizador. Los 53 rituales y su uso de tela están cotejados con el archivo del pack.</p><div class="mh-filters"><label>Buscar hechizo<input type="search" id="mh-spell-search" value="${esc(spellQuery)}" placeholder="Barrera, familiar, diamond…"></label><label>Familia<select id="mh-spell-category"><option value="all">Todas las familias</option>${[...new Set(data.spells.map(s=>s.category))].map(v=>`<option ${spellCategory===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Preparación<select id="mh-spell-form"><option value="all">Todas las formas</option>${Object.entries(formName).map(([k,v])=>`<option value="${k}" ${spellForm===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="mh-spell-results">${spellList()}</div>`;}
 function toolsView(){return `<h2>Calcula antes de fabricar</h2><p>Presupuestos con los valores de ATM10 8.1. No predicen tiempos de granja ni daño final de combate.</p><div class="mh-tools-grid"><form id="mh-catalyst-form" class="paper-panel mh-tool"><h3>Catalizadores por lote</h3><label>Hechizo<select name="spell">${data.spells.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Cantidad de círculos<input name="count" type="number" min="1" max="10000" value="1" required></label><label>Herramienta<select name="method"><option value="mortar">Mortar and Pestle · 2 polvos</option><option value="hammer">Hammer · 1 polvo</option></select></label><label>Formato<select name="scroll"><option value="true">Pergamino / tela</option><option value="false">Círculo en el suelo</option></select></label><button class="btn btn-primary" type="submit">Calcular materiales</button><div id="mh-catalyst-result" class="mh-calc-result" role="status"></div><small>La tela obligatoria se añade siempre. El cálculo agrupa cada polvo, redondea materiales y muestra sobrantes; no calcula desgaste de herramientas ni maná de lanzamiento.</small></form><form id="mh-morgan-form" class="paper-panel mh-tool"><h3>Crecimiento de Morgan</h3><label>Daño almacenado actual<input name="current" type="number" min="0" max="60" step="0.1" value="30" required></label><label>Daño objetivo<input name="target" type="number" min="0" max="60" step="0.1" value="60" required></label><label>Límite innato de tu espada<input name="cap" type="number" min="0" max="60" step="0.1" value="60" required></label><label>Tipo de aldeano (Minecraft)<select name="kind"><option value="adult">Adulto · +${data.values.MORGAN_ADULT_INCREASE}</option><option value="child">Cría · +${data.values.MORGAN_CHILD_INCREASE}</option></select></label><button class="btn btn-primary" type="submit">Calcular mejoras</button><div id="mh-morgan-result" class="mh-calc-result" role="status"></div><small>Usa el daño almacenado de Mahou, sin sumar encantamientos ni atributos. Cada mejora válida cuesta ${data.values.MORGAN_UPGRADE_MANA_COST} Mahou. No se modifica tu partida.</small></form></div>`;}
 function configRows(){const q=normalizeSearch(configQuery);const rows=data.config.filter(r=>(!configOnlyChanges||r.changed)&&normalizeSearch(r.key+' '+r.section+' '+(r.note||'')).includes(q));return `<p role="status">${rows.length} ajustes · ${data.config.length} claves cotejadas</p><div class="table-wrap"><table class="mh-config-table"><thead><tr><th scope="col">Clave / sección</th><th scope="col">ATM10 8.1</th><th scope="col">Mod sin ajustes</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><code>${esc(r.key)}</code><small>${esc(r.section)}</small>${r.note?`<p>${esc(r.note)}</p>`:''}</th><td><code>${esc(JSON.stringify(r.value))}</code></td><td><code>${esc(JSON.stringify(r.default))}</code></td></tr>`).join('')}</tbody></table></div>`;}
 function settings(){return `<h2>Qué cambia en ATM10 8.1</h2><p>Valores del archivo de configuración incluido en el ZIP oficial, comparados con los defaults de Mahou Tsukai ${esc(data.version)}. Un servidor puede aplicar otros ajustes.</p><div class="mh-callout"><strong>Tres diferencias que evitan perder materiales</strong><ul><li>El lago exige un tamaño mayor que ${data.values.POWER_CONSOLIDATION_LAKE_THRESHHOLD}; cada transformación cuesta ${format(data.values.POWER_CONSOLIDATION_SWORD_MANA_COST)} Mahou.</li><li>Caliburn conserva o sube su cap al reconsolidar. En una operación: 0–6 Nether Stars corresponden a 30, 35, 40, 45, 50, 55 y 60. Las tandas de estrellas no se suman.</li><li>La quest de drenaje menciona 10 de regeneración; el archivo fija 1. Ese 1 coincide con el default del JAR exacto: no es una reducción introducida por el pack.</li></ul></div><div class="mh-filters"><label>Buscar ajuste<input id="mh-config-search" type="search" value="${esc(configQuery)}" placeholder="MORGAN, MANA, FIRST_SORCERY…"></label><label class="check-inline"><input id="mh-config-changes" type="checkbox" ${configOnlyChanges?'checked':''}> Solo valores modificados por el pack</label></div><div id="mh-config-results">${configRows()}</div><section class="mh-bottom paper-panel"><h3>Controles y diagnóstico</h3><div class="mh-faq">${data.faq.map(x=>`<details><summary>${esc(x.question)}</summary><p>${esc(x.answer)}</p></details>`).join('')}</div><h3>Fuentes y cobertura</h3><p>${esc(data.scope)}</p><div class="mh-sources">${links(data.sources)}</div><p class="mh-muted">Recetas estáticas y rituales verificados por extracción; redacción editorial en español. No se ha ejecutado Minecraft ni consultado la configuración privada de tu servidor.</p></section>`;}
 function view(){return `<div class="mahou-workspace">${header()}${({overview,guides:guide,roadmap,spells,tools:toolsView,settings}[tab]||overview)()}</div>`;}
 function input(el){if(el.id==='mh-spell-search')spellQuery=el.value;else if(el.id==='mh-spell-category')spellCategory=el.value;else if(el.id==='mh-spell-form')spellForm=el.value;else if(el.id==='mh-config-search')configQuery=el.value;else if(el.id==='mh-config-changes')configOnlyChanges=el.checked;else return false;const spell=el.id.startsWith('mh-spell');document.querySelector(spell?'#mh-spell-results':'#mh-config-results').innerHTML=spell?spellList():configRows();return true;}
 function reset(){spellQuery='';spellCategory='all';spellForm='all';navigate('mahou/spells');}
 function submit(form){if(!['mh-catalyst-form','mh-morgan-form'].includes(form.id))return false;const fields=Object.fromEntries(new FormData(form));if(form.id==='mh-morgan-form'){const r=morganBudget(fields,data.values);document.querySelector('#mh-morgan-result').innerHTML=r.error?`<p>${esc(r.error)}</p>`:`<strong>${format(r.kills)} mejoras válidas</strong><p>${format(r.mana)} Mahou acumulados · +${r.gain} por evento.</p><p>Techo aplicable: ${r.ceiling}. Mantén al menos ${data.values.MORGAN_UPGRADE_MANA_COST} disponibles en cada mejora.</p>`;}else{const s=data.spells.find(s=>s.id===fields.spell),r=catalystBudget(s,fields.count,fields.method,fields.scroll==='true');document.querySelector('#mh-catalyst-result').innerHTML=r.error?`<p>${esc(r.error)}</p>`:`<strong>Materiales para ${r.quantity} círculos</strong><ul>${r.powders.map(x=>`<li>${x.count} × ${esc(name(x.id))}: ${x.raw} unidades del material original${x.surplus?' · sobra '+x.surplus+' polvo':''}.</li>`).join('')}<li>${r.cloth} × Spell Cloth${r.cloth?' · '+Math.ceil(r.cloth/4)+' de lana blanca para fabricarla en lotes de 4':''}.</li></ul><p>Usa ${esc(r.tools)}${r.cloth?' y Dagger para la tela':''}. Ten herramientas utilizables; no se multiplican como materiales consumidos.</p>`;}return true;}
 return {route,view,input,submit,reset,progress};
}
